<script setup lang="ts">
import type { AIEvidence } from '../ai-types'
import type { ProcessPeak } from '../process-types'
defineProps<{evidence:AIEvidence;analysisId?:string}>()
const when=(n:number)=>new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'}).format(n)
const value=(v:unknown,places=3)=>v===null||v===undefined?'Sem leitura':typeof v==='number'?v.toLocaleString('pt-BR',{maximumFractionDigits:places}):String(v)
const labels:Record<string,string>={hours_per_day:'Horas de uso por dia',days:'Dias projetados',window_hours:'Horas na janela-base',tariff_brl_per_kwh:'Tarifa usada (R$/kWh)',projected_kwh:'Energia projetada (kWh)',projected_cost_brl:'Custo projetado (R$)',metric:'Métrica',unit:'Unidade',total_buckets:'Intervalos na janela',observed_buckets:'Intervalos com dados',before_mean:'Média da primeira metade',after_mean:'Média da segunda metade',before_count:'Intervalos na primeira metade',after_count:'Intervalos na segunda metade',delta:'Diferença',median:'Mediana de referência',mad:'Desvio absoluto mediano',threshold:'Limiar de desvio',sample_count:'Amostras',tariff_origin:'Origem da tarifa'}
const scalars=(data:Record<string,unknown>)=>Object.entries(data).filter(([k,v])=>k in labels&&(v===null||['string','number','boolean'].includes(typeof v)))
const rows=(data:Record<string,unknown>)=>(Array.isArray(data.points)?data.points:[]) as {time_ms:number;value:number|null}[]
const preview=(data:Record<string,unknown>)=>rows(data).length>12?[...rows(data).slice(0,6),...rows(data).slice(-6)]:rows(data)
</script>
<template>
<section class="ai-evidence" aria-label="Dados e método da evidência">
  <div class="ai-evidence-heading"><h3>Dados que sustentam a afirmação</h3><span class="status-badge positive">Consulta registrada</span></div>
  <p class="muted">{{when(evidence.window.start_ms)}} até {{when(evidence.window.end_ms)}} · Horário de Brasília</p>
  <p class="ai-method">{{evidence.method}}</p>
  <div v-if="analysisId&&evidence.tool==='calculate_energy_cost'&&evidence.data.provenance" class="ai-raw-download"><a class="button small" :href="`/api/ai/analyses/${encodeURIComponent(analysisId)}/evidence/${evidence.id}/raw.csv`">Baixar leituras de origem (CSV)</a><p class="muted">Inclui a leitura anterior à janela, necessária para calcular a variação inicial do contador. Este download fica no seu PC.</p></div>
  <div v-if="evidence.tool==='inspect_process_activity'" class="ai-raw-download"><a v-if="analysisId" class="button small" :href="`/api/ai/analyses/${encodeURIComponent(analysisId)}/evidence/${evidence.id}/processes.csv`">Baixar evidências de processos (CSV)</a><p class="muted">Nomes, PIDs e contadores ficam neste PC. A IA recebeu apelidos e valores calculados. O CSV contém somente os processos associados nesta consulta.</p></div>
  <template v-if="evidence.tool==='inspect_process_activity'"><section v-for="peak in (evidence.data.peaks as ProcessPeak[])" :key="peak.index"><p class="process-evidence-note"><strong>{{value(peak.value,2)}} {{evidence.data.unit}}</strong> · {{when(peak.start_ms)}} até {{when(peak.end_ms)}} · média do intervalo, sem prova de causa.</p><div v-if="peak.matches.length" class="table-scroll" tabindex="0" role="region" aria-label="Processos com intervalos sobrepostos"><table class="sensor-table process-evidence-table"><thead><tr><th>Aplicativo / processo local</th><th>Apelido para a IA</th><th>CPU da máquina</th><th>Intervalos de origem</th></tr></thead><tbody><tr v-for="match in peak.matches" :key="match.alias"><td>{{match.name}}<small v-if="match.members_only">Somente processos retidos</small></td><td>{{match.alias}}</td><td>{{value(match.cpu_percent,4)}}%</td><td><div v-for="entry in match.entries" :key="`${entry.pid}-${entry.start_ticks}`">{{entry.name}} · PID {{entry.pid}} · {{when(entry.interval_start_ms!)}} até {{when(entry.interval_end_ms)}}<small v-if="entry.application">{{entry.application.method==='parent_rule'?'Parentesco registrado':entry.application.method==='name_rule'?'Regra de nome':'Aplicativo não identificado'}}</small><small v-if="entry.ancestors?.length">{{entry.name}} ← {{entry.ancestors.map(p=>p.name+' (PID '+p.pid+')').join(' ← ')}}</small></div></td></tr></tbody></table></div><p v-else class="muted process-evidence-note">Nenhum intervalo compatível foi encontrado nas varreduras retidas.</p></section></template>
  <dl v-if="scalars(evidence.data).length" class="ai-facts-grid"><div v-for="[key,item] in scalars(evidence.data)" :key="key"><dt>{{labels[key]}}</dt><dd>{{value(item)}}</dd></div></dl>
  <div v-if="evidence.tool!=='project_monthly_cost'&&Array.isArray(evidence.data.components)" class="table-scroll" tabindex="0" role="region" aria-label="Tabela de evidências"><table class="sensor-table"><caption>Resultados calculados pela aplicação</caption><thead><tr><th>Componente</th><th>Energia (Wh)</th><th>Custo (R$)</th><th>Cobertura temporal</th></tr></thead><tbody><tr v-for="(c,i) in (evidence.data.components as Record<string,unknown>[])" :key="i"><td>{{String(c.id).toUpperCase()}}</td><td>{{typeof c.energy_kwh==='number'?value(c.energy_kwh*1000,2):'Indisponível'}}</td><td>{{c.cost_brl===null?'Indisponível':value(c.cost_brl,4)}}</td><td>{{value(c.coverage_percent,1)}}%</td></tr></tbody></table></div>
  <div v-if="evidence.tool==='project_monthly_cost'&&Array.isArray(evidence.data.components)" class="table-scroll" tabindex="0" role="region" aria-label="Projeção por componente"><table class="sensor-table"><caption>Cenário de {{value(evidence.data.hours_per_day,1)}} h/dia durante 30 dias</caption><thead><tr><th>Componente</th><th>Horas observadas</th><th>Cobertura</th><th>Média (W)</th><th>Projeção (kWh)</th><th>Projeção (R$)</th></tr></thead><tbody><tr v-for="(c,i) in (evidence.data.components as Record<string,unknown>[])" :key="i"><td>{{String(c.id).toUpperCase()}}</td><td>{{value(c.observed_hours,2)}}</td><td>{{value(c.coverage_percent,1)}}%</td><td>{{typeof c.hourly_kwh==='number'?value(c.hourly_kwh*1000,2):'Indisponível'}}</td><td>{{value(c.projected_kwh,3)}}</td><td>{{c.projected_cost_brl===null?'Falta tarifa':value(c.projected_cost_brl,2)}}</td></tr></tbody></table></div>
  <div v-if="Array.isArray(evidence.data.anomalies)&&evidence.data.anomalies.length" class="table-scroll" tabindex="0" role="region" aria-label="Tabela de evidências"><table class="sensor-table"><caption>Desvios identificados</caption><thead><tr><th>Horário</th><th>Valor ({{evidence.data.unit}})</th></tr></thead><tbody><tr v-for="(point,i) in (evidence.data.anomalies as {time_ms:number;value:number}[])" :key="i"><td>{{when(point.time_ms)}}</td><td>{{value(point.value)}}</td></tr></tbody></table></div>
  <div v-if="rows(evidence.data).length" class="table-scroll ai-evidence-points" tabindex="0" role="region" aria-label="Intervalos da evidência"><table class="sensor-table"><caption>Intervalos agregados usados na consulta</caption><thead><tr><th>Horário</th><th>Valor {{evidence.data.unit?`(${evidence.data.unit})`:''}}</th></tr></thead><tbody><tr v-for="(point,i) in preview(evidence.data)" :key="i"><td>{{when(point.time_ms)}}</td><td>{{value(point.value)}}</td></tr></tbody></table><p v-if="rows(evidence.data).length>12" class="muted">Prévia dos seis primeiros e seis últimos intervalos. Todos os valores estão nos detalhes completos abaixo.</p></div>
  <details><summary>Dados completos e consulta</summary><pre>{{JSON.stringify(evidence,null,2)}}</pre></details>
</section>
</template>
